	PALETTEENTRY *p; // eax@25
	int palIndex; // ecx@25
	unsigned int palNum; // [sp+44h] [bp-42Ch]@24
	PALETTEENTRY *pal; // [sp+48h] [bp-428h]@24
	int pdwHeight; // [sp+60h] [bp-410h]@1
	int pdwWidth; // [sp+64h] [bp-40Ch]@1
	HWND parent_1; // [sp+68h] [bp-408h]@1
