			SetWindowTextA( GetDlgItem( hdlg, ID_MAINMENU_CLASSIC ),       "\x87\x88\x89 DIABLO" );          // Keullaesik DIABLO
			SetWindowTextA( GetDlgItem( hdlg, ID_MAINMENU_COLISEUM ),      "\x8A\x8B\x8C\x8D (PVP)" );       // Kollosseum
